def min_lexicographic_string(n, k, s):
    # Count the number of '0's in the string
    zero_count = s.count('0')

    # If there are no '0's or k is greater than or equal to the number of possible swaps
    if zero_count == 0 or k >= zero_count * (n - zero_count):
        return ''.join(sorted(s))

    result = list(s)
    swaps = 0

    # Try to place '0's as early as possible
    for i in range(n):
        if result[i] == '1':
            # Find the next '0' to swap
            for j in range(i + 1, n):
                if result[j] == '0':
                    # Swap '1' and '0'
                    result[i], result[j] = result[j], result[i]
                    swaps += j - i
                    break
            # If we have used up all allowed swaps, stop
            if swaps > k:
                break

    return ''.join(result)

